/// A new item that appears in a CreateItem request.
///
/// See <https://learn.microsoft.com/en-us/exchange/client-developer/web-service-reference/items>
// N.B.: Commented-out variants are not yet implemented.
#[non_exhaustive]
#[derive(Debug, XmlSerialize)]
#[xml_struct(variant_ns_prefix = "t")]
pub enum Item {
    // Item(Item),
    Message(Message),

#[derive(Debug, Default, XmlSerialize)]
pub struct Message {
    /// The MIME content of the item.
    #[xml_struct(ns_prefix = "t")]
    pub mime_content: Option<MimeContent>,
    // Whether to request a delivery receipt.
    #[xml_struct(ns_prefix = "t")]
    pub is_delivery_receipt_requested: Option<bool>,
    // The message ID for the message, semantically identical to the Message-ID
    // header.
    #[xml_struct(ns_prefix = "t")]
    pub internet_message_id: Option<String>,
    // Recipients to include as Bcc, who won't be included in the MIME content.
    #[xml_struct(ns_prefix = "t")]
    pub bcc_recipients: Option<ArrayOfRecipients>,

/// An email message.
///
/// See <https://learn.microsoft.com/en-us/exchange/client-developer/web-service-reference/message-ex15websvcsotherref>
#[derive(Clone, Debug, Default, Deserialize, XmlSerialize, PartialEq, Eq)]
#[serde(rename_all = "PascalCase")]
pub struct Message {
    /// The MIME content of the item.
    #[xml_struct(ns_prefix = "t")]
    pub mime_content: Option<MimeContent>,

// Create a new message using the default values, and set the ones we
// need.
let message = Message {
    mime_content: Some(MimeContent {
        character_set: None,
        content: BASE64_STANDARD.encode(&self.mime_content),
    }),
    is_delivery_receipt_requested: Some(self.should_request_dsn),
    internet_message_id: Some(self.message_id.clone()),
    bcc_recipients,
    ..Default::default()
};

let create_item = CreateItem {
    items: vec![RealItem::Message(message)],

    // We don't need EWS to copy messages to the Sent folder after
    // they've been sent, because the internal MessageSend module
    // already takes care of it and will include additional headers we
    // don't send to EWS (such as Bcc).
    message_disposition: Some(MessageDisposition::SendOnly),
    saved_item_folder_id: None,
};

#[test]
fn test_deserialize_create_item_response() {
    let content = r#"
        <CreateItemResponse
            xmlns:m="http://schemas.microsoft.com/exchange/services/2006/messages"
            xmlns:t="http://schemas.microsoft.com/exchange/services/2006/types"
            xmlns="http://schemas.microsoft.com/exchange/services/2006/messages">
          <m:ResponseMessages>
            <m:CreateItemResponseMessage ResponseClass="Success">
              <m:ResponseCode>NoError</m:ResponseCode>
              <m:Items />
            </m:CreateItemResponseMessage>
          </m:ResponseMessages>
        </CreateItemResponse>"#;

    let expected = CreateItemResponse {
        response_messages: ResponseMessages {
            response_messages: vec![ResponseClass::Success(ItemResponseMessage {
                items: Items { inner: vec![] },
            })],
        },
    };

    assert_deserialized_content(content, expected);
